    "title": "TransitWeave Inc. \u2014 a public-transit trip-planning API that aggregates GTFS feeds, real-time vehicle positions, and rider alerts for regional agencies. API",
    "served_at": "/openapi.json",
    "description": "OpenAPI 3.1 spec for the TransitWeave Inc. \u2014 a public-transit trip-planning API that aggregates GTFS feeds, real-time vehicle positions, and rider alerts for regional agencies. API, inlined below. All endpoints are relative paths on the same host; construct requests with execute().",
    "document": {
      "openapi": "3.1.0",
      "info": {
        "title": "TransitWeave Inc. \u2014 a public-transit trip-planning API that aggregates GTFS feeds, real-time vehicle positions, and rider alerts for regional agencies. API",
        "version": "1.0.0",
        "description": "TransitWeave Routing API: a REST service that ingests transit feeds, builds journey plans, and lets integrators publish service alerts and stage feed snapshots before agencies go live."
      },
      "servers": [
        {
          "url": "http://localhost:9001"
        }
      ],
      "paths": {
        "/openapi.json": {
          "get": {
            "summary": "OpenAPI spec doc"
          }
        },
        "/v3/oauth/token": {
          "post": {
            "summary": "OAuth client_credentials",
            "security": [
              {
                "none": []
              }
            ]
          }
        },
        "/v3/feeds": {
          "get": {
            "summary": "List/search feeds",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v2/feeds": {
          "get": {
            "summary": "DEPRECATED feed list",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/feeds/{feed_id}/snapshots/latest": {
          "get": {
            "summary": "Latest staged snapshot for a feed",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/snapshots/{snapshot_id}/stops": {
          "get": {
            "summary": "Stops in a snapshot",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/alerts": {
          "post": {
            "summary": "Create a service alert draft",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/alerts/{alert_id}/publish": {
          "post": {
            "summary": "Publish a drafted alert (partial-write trap)",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/alerts/{alert_id}": {
          "get": {
            "summary": "Fetch alert state",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/feeds/{feed_id}/live/digest": {
          "get": {
            "summary": "Live feed digest (verify alert landed)",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        }
      }
    }
  },
